def parse_desktop_file(path):
    try:
        with open(path, "r", encoding="utf-8", errors="strict") as f:
            lines = f.read().splitlines()
    except:
        return None
    found_header = False
    name = None
    exec_str = None
    mimetypes_raw = None
    in_desktop = False
    for line in lines:
        stripped_leading = line.lstrip()
        if stripped_leading == "":
            continue
        if stripped_leading.startswith("#"):
            continue
        s = line.strip()
        if s.startswith("[") and s.endswith("]"):
            if s == "[Desktop Entry]":
                found_header = True
                in_desktop = True
            else:
                in_desktop = False
            continue
        if not in_desktop:
            continue
        if "=" not in line:
            continue
        idx = line.find("=")
        key_raw = line[:idx]
        val = line[idx+1:]
        key = key_raw.lstrip()
        if key == "Name":
            name = val
        elif key == "Exec":
            exec_str = val
        elif key == "MimeType":
            mimetypes_raw = val
    if not found_header:
        return None
    if name is None or name == "":
        return None
    if exec_str is None or exec_str == "":
        return None
    mimetypes = []
    if mimetypes_raw is not None:
        parts = mimetypes_raw.split(";")
        for p in parts:
            if p == "":
